 import React, { useState, useEffect } from 'react'
import { useParams, Link, useNavigate } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import FollowButton from '../components/follow/FollowButton'
import { Users, UserPlus, ArrowLeft, Loader } from 'lucide-react'

export default function Followers() {
    const { userId, type } = useParams()
    const { user } = useAuth()
    const navigate = useNavigate()
    const [users, setUsers] = useState([])
    const [loading, setLoading] = useState(true)
    const [profile, setProfile] = useState(null)
    const [error, setError] = useState(null)

    useEffect(() => {
        // Debug: log the params
        console.log('Params:', { userId, type })
        
        if (!userId || !type) {
            setError('Invalid URL parameters')
            setLoading(false)
            return
        }
        
        loadData()
    }, [userId, type])

    const loadData = async () => {
        setLoading(true)
        setError(null)
        
        try {
            console.log('Loading data for:', { userId, type })
            
            // Get user profile
            const { data: profileData, error: profileError } = await supabase
                .from('profiles')
                .select('id, username, full_name, avatar_url')
                .eq('id', userId)
                .single()

            if (profileError) {
                console.error('Profile error:', profileError)
                throw profileError
            }
            setProfile(profileData)
            console.log('Profile loaded:', profileData)

            // Get followers or following
            let query
            if (type === 'followers') {
                // Users who follow this person (follower_id is the person following)
                query = supabase
                    .from('followers')
                    .select(`
                        follower_id,
                        profiles:follower_id (
                            id,
                            username,
                            full_name,
                            avatar_url,
                            is_verified
                        )
                    `)
                    .eq('following_id', userId)
            } else if (type === 'following') {
                // Users this person follows (following_id is the person being followed)
                query = supabase
                    .from('followers')
                    .select(`
                        following_id,
                        profiles:following_id (
                            id,
                            username,
                            full_name,
                            avatar_url,
                            is_verified
                        )
                    `)
                    .eq('follower_id', userId)
            } else {
                throw new Error('Invalid type: ' + type)
            }

            const { data, error } = await query

            if (error) {
                console.error('Query error:', error)
                throw error
            }

            console.log('Raw data:', data)

            // Extract users from the nested structure
            let userList = []
            if (data && data.length > 0) {
                userList = data
                    .map(item => {
                        if (type === 'followers') {
                            return item.profiles
                        } else {
                            return item.profiles
                        }
                    })
                    .filter(profile => profile !== null && profile !== undefined)
            }

            console.log('User list:', userList)
            setUsers(userList)

        } catch (error) {
            console.error('Error loading data:', error)
            setError(error.message || 'Failed to load data')
        } finally {
            setLoading(false)
        }
    }

    // Handle loading state
    if (loading) {
        return (
            <div className="max-w-2xl mx-auto px-4 py-6">
                <div className="bg-white rounded-xl shadow-md p-8 text-center">
                    <Loader className="w-8 h-8 text-gray-400 animate-spin mx-auto" />
                    <p className="text-gray-500 mt-4">Loading...</p>
                </div>
            </div>
        )
    }

    // Handle error state
    if (error) {
        return (
            <div className="max-w-2xl mx-auto px-4 py-6">
                <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
                    <p className="font-medium">Error loading data</p>
                    <p className="text-sm">{error}</p>
                    <button 
                        onClick={() => navigate(-1)}
                        className="mt-2 text-sm text-red-600 hover:text-red-800 underline"
                    >
                        Go Back
                    </button>
                </div>
            </div>
        )
    }

    // Handle no profile found
    if (!profile) {
        return (
            <div className="max-w-2xl mx-auto px-4 py-6">
                <div className="bg-white rounded-xl shadow-md p-8 text-center">
                    <p className="text-gray-500">User not found</p>
                    <button 
                        onClick={() => navigate('/')}
                        className="mt-4 text-gray-600 hover:text-gray-800 underline"
                    >
                        Go Home
                    </button>
                </div>
            </div>
        )
    }

    return (
        <div className="max-w-2xl mx-auto px-4 py-6">
            {/* Header */}
            <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                <div className="flex items-center gap-3">
                    <Link 
                        to={`/profile/${userId}`}
                        className="p-2 hover:bg-gray-100 rounded-lg transition"
                    >
                        <ArrowLeft size={20} className="text-gray-600" />
                    </Link>
                    <div>
                        <h1 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                            {type === 'followers' ? (
                                <Users size={20} className="text-gray-500" />
                            ) : (
                                <UserPlus size={20} className="text-gray-500" />
                            )}
                            {type === 'followers' ? 'Followers' : 'Following'}
                        </h1>
                        <p className="text-sm text-gray-500">
                            @{profile?.username || 'user'}
                        </p>
                    </div>
                    <div className="ml-auto text-sm text-gray-400">
                        {users.length} {type === 'followers' ? 'followers' : 'following'}
                    </div>
                </div>
            </div>

            {/* Users List */}
            {users.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">👀</div>
                    <p className="text-gray-500 text-lg">
                        {type === 'followers' 
                            ? 'No followers yet' 
                            : 'Not following anyone yet'}
                    </p>
                    <p className="text-gray-400 text-sm mt-1">
                        {type === 'followers' 
                            ? 'When people follow you, they\'ll appear here' 
                            : 'Follow other users to see them here'}
                    </p>
                    {type === 'following' && user?.id === userId && (
                        <Link 
                            to="/community"
                            className="inline-block mt-4 text-gray-600 hover:text-gray-800 underline"
                        >
                            Find people to follow
                        </Link>
                    )}
                </div>
            ) : (
                <div className="space-y-2">
                    {users.map((userItem) => (
                        <div 
                            key={userItem.id} 
                            className="bg-white rounded-xl shadow-md p-4 flex items-center justify-between hover:shadow-lg transition"
                        >
                            <Link 
                                to={`/profile/${userItem.id}`} 
                                className="flex items-center gap-3 hover:opacity-80 flex-1"
                            >
                                <div className="w-10 h-10 bg-gray-200 rounded-full flex items-center justify-center text-gray-600 font-bold text-sm overflow-hidden flex-shrink-0">
                                    {userItem.avatar_url ? (
                                        <img 
                                            src={userItem.avatar_url} 
                                            alt={userItem.username} 
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        userItem.username?.[0]?.toUpperCase() || 'U'
                                    )}
                                </div>
                                <div>
                                    <div className="font-semibold text-gray-800 flex items-center gap-1.5">
                                        {userItem.full_name || userItem.username}
                                        {userItem.is_verified && (
                                            <span className="text-blue-500 text-sm font-bold">✓</span>
                                        )}
                                    </div>
                                    <div className="text-sm text-gray-500">@{userItem.username}</div>
                                </div>
                            </Link>
                            {userItem.id !== user?.id && (
                                <FollowButton 
                                    userId={userItem.id} 
                                    username={userItem.username}
                                    onFollowChange={loadData}
                                />
                            )}
                        </div>
                    ))}
                </div>
            )}
        </div>
    )
}
